static ImagePtr cloneBitmap(Image*image){
 if(!image||image->GetLastStatus()!=Ok)return {};UINT w=image->GetWidth(),h=image->GetHeight();if(!w||!h||w>20000||h>20000||(uint64_t)w*h>80000000)return {};
 ImagePtr b=std::make_shared<Bitmap>(w,h,PixelFormat32bppARGB);{Graphics g(b.get());g.SetCompositingMode(CompositingModeSourceCopy);g.DrawImage(image,0,0,w,h);}return b;
}
static CapturePixels::Image readPixels(Bitmap*b){
 CapturePixels::Image p;p.w=(int)b->GetWidth();p.h=(int)b->GetHeight();p.pixels.resize((size_t)p.w*p.h);BitmapData data;Rect r(0,0,p.w,p.h);
 if(b->LockBits(&r,ImageLockModeRead,PixelFormat32bppARGB,&data)!=Ok){p.pixels.clear();return p;}
 for(int y=0;y<p.h;y++)memcpy(p.pixels.data()+(size_t)y*p.w,(BYTE*)data.Scan0+(ptrdiff_t)y*data.Stride,(size_t)p.w*4);b->UnlockBits(&data);return p;
}
static ImagePtr fromPixels(const CapturePixels::Image&p){
 if(p.w<1||p.h<1||p.pixels.size()!=(size_t)p.w*p.h)return {};auto out=std::make_shared<Bitmap>(p.w,p.h,PixelFormat32bppARGB);BitmapData data;Rect r(0,0,p.w,p.h);
 if(out->LockBits(&r,ImageLockModeWrite,PixelFormat32bppARGB,&data)!=Ok)return {};
 for(int y=0;y<p.h;y++)memcpy((BYTE*)data.Scan0+(ptrdiff_t)y*data.Stride,p.pixels.data()+(size_t)y*p.w,(size_t)p.w*4);out->UnlockBits(&data);return out;
}
static void drawLayer(Bitmap*target,const Layer&l){
 RectF box=floatBounds(l);
 if((l.type==RECTANGLE&&l.filled)||(l.type==TEXT&&l.textBackground)){auto pixels=readPixels(target);if(!pixels.pixels.empty()){CapturePixels::fillRect(pixels,{(int)box.X,(int)box.Y,(int)box.Width,(int)box.Height},l.type==TEXT?0xffffffff:l.color.GetValue());BitmapData data;Rect area(0,0,pixels.w,pixels.h);if(target->LockBits(&area,ImageLockModeWrite,PixelFormat32bppARGB,&data)==Ok){for(int y=0;y<pixels.h;y++)memcpy((BYTE*)data.Scan0+(ptrdiff_t)y*data.Stride,pixels.pixels.data()+(size_t)y*pixels.w,(size_t)pixels.w*4);target->UnlockBits(&data);}}}

 if(l.type==MOSAIC||l.type==BLUR){auto p=readPixels(target);if(p.pixels.empty())return;CapturePixels::Rect r={(int)box.X,(int)box.Y,(int)box.Width,(int)box.Height};if(l.type==MOSAIC)CapturePixels::mosaic(p,r,(int)l.width*3+6);else CapturePixels::blur(p,r,(int)l.width*2+4);
 BitmapData data;Rect full(0,0,p.w,p.h);if(target->LockBits(&full,ImageLockModeWrite,PixelFormat32bppARGB,&data)==Ok){for(int y=0;y<p.h;y++)memcpy((BYTE*)data.Scan0+(ptrdiff_t)y*data.Stride,p.pixels.data()+(size_t)y*p.w,(size_t)p.w*4);target->UnlockBits(&data);}return;}
 Graphics g(target);g.SetSmoothingMode(SmoothingModeAntiAlias);g.SetTextRenderingHint(TextRenderingHintAntiAliasGridFit);g.SetInterpolationMode(InterpolationModeHighQualityBicubic);
 Pen pen(l.color,l.width);pen.SetLineJoin(LineJoinRound);pen.SetStartCap(LineCapRound);pen.SetEndCap(LineCapRound);SolidBrush brush(l.color);
 if(l.image){g.DrawImage(l.image.get(),box);return;}
 switch(l.type){
 case RECTANGLE:case CROP:g.DrawRectangle(&pen,box);break;
 case LINE:g.DrawLine(&pen,l.x,l.y,l.x+l.w,l.y+l.h);break;
 case CHECKMARK:{PointF v[]={PointF(l.x,l.y+l.h*0.5f),PointF(l.x+l.w*0.35f,l.y+l.h),PointF(l.x+l.w,l.y)};g.DrawLines(&pen,v,3);break;}
 case ELLIPSE:if(l.filled)g.FillEllipse(&brush,box);g.DrawEllipse(&pen,box);break;
 case COVER:g.FillRectangle(&brush,box);break;
 case ARROW:{PointF a(l.x,l.y),b(l.x+l.w,l.y+l.h);g.DrawLine(&pen,a,b);float angle=std::atan2(l.h,l.w),len=std::max(12.0f,l.width*4);PointF head[]={b,PointF(b.X-len*std::cos(angle-0.45f),b.Y-len*std::sin(angle-0.45f)),PointF(b.X-len*std::cos(angle+0.45f),b.Y-len*std::sin(angle+0.45f))};g.FillPolygon(&brush,head,3);break;}
 case FREEHAND:if(l.points.size()>1)g.DrawLines(&pen,l.points.data(),(INT)l.points.size());break;
 case TEXT:{Font font(L"Malgun Gothic",(REAL)l.font,FontStyleRegular,UnitPixel);StringFormat format;format.SetFormatFlags(StringFormatFlagsLineLimit);g.DrawString(l.text.c_str(),-1,&font,box,&format,&brush);break;}
 default:break;
 }
}
static ImagePtr render(){
 if(!hasImage())return {};if(!cacheDirty&&cached)return cached;auto out=cloneBitmap(document.base.get());if(!out)return {};for(const auto&l:document.layers)drawLayer(out.get(),l);cached=out;cacheDirty=false;return out;
}
static const wchar_t*toolName(Tool t){static const wchar_t*names[]={L"선택·이동",L"사각형",L"원·타원",L"화살표",L"펜",L"글자",L"모자이크",L"흐림",L"완전 가리기",L"수동 누끼",L"선",L"체크 표시",L"자르기"};return names[(int)t];}
static bool shapeTool(Tool t){return t==RECTANGLE||t==ELLIPSE||t==ARROW||t==LINE||t==CHECKMARK;}
static void updateLayers(){
 for(int t=0;t<=CROP;t++)SendMessageW(GetDlgItem(mainWindow,3000+t),BM_SETCHECK,tool==t?BST_CHECKED:BST_UNCHECKED,0);SendMessageW(GetDlgItem(mainWindow,3090),BM_SETCHECK,tool==recentShape?BST_CHECKED:BST_UNCHECKED,0);
 const Layer*current=selected>=0&&selected<(int)document.layers.size()?&document.layers[selected]:nullptr;EnableWindow(GetDlgItem(mainWindow,FILLSHAPE),tool==RECTANGLE||tool==ELLIPSE||(current&&(current->type==RECTANGLE||current->type==ELLIPSE)));EnableWindow(GetDlgItem(mainWindow,TEXTBACKGROUND),tool==TEXT||(current&&current->type==TEXT));SendMessageW(GetDlgItem(mainWindow,FILLSHAPE),BM_SETCHECK,(current?current->filled:fillShapes)?BST_CHECKED:BST_UNCHECKED,0);SendMessageW(GetDlgItem(mainWindow,TEXTBACKGROUND),BM_SETCHECK,(current?current->textBackground:fillTextBackground)?BST_CHECKED:BST_UNCHECKED,0);

 SendMessageW(layerList,LB_RESETCONTENT,0,0);for(int i=(int)document.layers.size()-1;i>=0;i--){const Layer&l=document.layers[i];wchar_t label[256];swprintf(label,256,L"%d · %ls%ls",i+1,l.image?GalaxyTr(L"그림"):GalaxyTr(toolName(l.type)),l.type==TEXT?GalaxyTr(L" (글자)"):L"");SendMessageW(layerList,LB_ADDSTRING,0,(LPARAM)label);}
 if(selected>=0&&selected<(int)document.layers.size())SendMessageW(layerList,LB_SETCURSEL,document.layers.size()-1-selected,0);else SendMessageW(layerList,LB_SETCURSEL,(WPARAM)-1,0);
 EnableWindow(GetDlgItem(mainWindow,UNDO),!undoStack.empty());EnableWindow(GetDlgItem(mainWindow,REDO),!redoStack.empty());EnableWindow(GetDlgItem(mainWindow,DELETEBTN),selected>=0);
}
