static void addImage(ImagePtr image){if(!image)return;if(!hasImage()){setDocument(image,L"image");return;}pushUndo();Layer l;l.image=image;l.x=16;l.y=16;float ratio=std::min(1.0f,std::min(document.base->GetWidth()*0.65f/image->GetWidth(),document.base->GetHeight()*0.65f/image->GetHeight()));l.w=image->GetWidth()*ratio;l.h=image->GetHeight()*ratio;document.layers.push_back(l);selected=(int)document.layers.size()-1;tool=SELECT;SendMessageW(GetDlgItem(mainWindow,TOOL),CB_SETCURSEL,SELECT,0);changed();status(L"그림을 겹쳤습니다. 드래그해 이동하고 오른쪽 아래 점을 잡아 크기를 바꾸세요.");}
