 if(!polygon.empty()){Pen pen(Color(255,25,120,240),2);SolidBrush b(Color(255,25,120,240));std::vector<PointF>points;for(auto p:polygon){points.emplace_back(offsetX+(float)p.x*zoom,offsetY+(float)p.y*zoom);g.FillEllipse(&b,points.back().X-3,points.back().Y-3,6.0f,6.0f);}if(points.size()>1)g.DrawLines(&pen,points.data(),(INT)points.size());}
