bool CopyClipboardImage(const wstring&path,std::string&error){
 // The authenticated agent resolves an asset ID first. Bound and validate the PNG
 // again here before decoding; no arbitrary executable or reparse file is opened.
 if(path.empty()||path.size()>=32760||path.find_first_of(L"\r\n")!=wstring::npos||_wcsicmp(PathFindExtensionW(path.c_str()),L".png")){error="invalidPath";return false;}
 HANDLE file=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr);
 if(file==INVALID_HANDLE_VALUE){error="invalidPath";return false;}BY_HANDLE_FILE_INFORMATION info={};LARGE_INTEGER length={};
 bool valid=GetFileInformationByHandle(file,&info)&&!(info.dwFileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT))&&GetFileSizeEx(file,&length)&&length.QuadPart>=8&&length.QuadPart<=320000000;
 std::vector<BYTE>bytes(valid?(size_t)length.QuadPart:0);DWORD read=0;valid=valid&&ReadFile(file,bytes.data(),(DWORD)bytes.size(),&read,nullptr)&&read==bytes.size();CloseHandle(file);
 if(!valid||!CaptureCopyPolicy::boundedPng(bytes.data(),bytes.size())){error="invalidImage";return false;}
 auto image=imageFromBytes(bytes.data(),bytes.size());if(!image){error="invalidImage";return false;}
 if(!publishClipboardImage(image.get(),bytes.data(),bytes.size())){error="clipboardFailed";return false;}return true;
}
